def pit_value(versions, as_of):
    """versions: (period, value, published) records, ISO dates.
    Returns {period: value} using, for each period, the latest
    version published on or before as_of."""
    best = {}
    for period, value, published in versions:
        if published <= as_of:
            if period not in best or published >= best[period][1]:
                best[period] = (value, published)
    return {p: v for p, (v, _) in best.items()}

def leak_audit(features, label_start, pipeline, universe, log):
    """features: {name: day its inputs are known}
    label_start: day the prediction is made
    pipeline: [(step, fit_on)], fit_on "all", "train" or "none"
    universe: {"members": "today" or "as_of",
               "full_history_only": bool,
               "delisting": "actual" or "zero"}
    log: [(action, config)] as in trials_log_count
    Returns {"target": [...], "transform": [...],
             "survivorship": [...], "trials": n}."""
    target = sorted(n for n, t in features.items() if t > label_start)
    transform = [step for step, fit_on in pipeline if fit_on == "all"]
    surv = []
    if universe.get("members") == "today":
        surv.append("today's members")
    if universe.get("full_history_only"):
        surv.append("full history only")
    if universe.get("delisting") == "zero":
        surv.append("zero delisting return")
    trials = len({c for a, c in log if a in ("fit", "look")})
    return {"target": target, "transform": transform,
            "survivorship": surv, "trials": trials}
